$('#cancel-batch').onclick=()=>$('#cancel').click();
$('#run-witness').onclick=()=>{if(!result)return;$('#query').value=result.witness.text;tokenCount();invalidate();$('#run-query').click()};
function parseCSV(text){const rows=[];let row=[],cell='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){cell+='"';i++}else quote=!quote}else if(c===','&&!quote){row.push(cell);cell=''}else if(c==='\n'&&!quote){row.push(cell.replace(/\r$/,''));if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(quote)throw Error('CSV có dấu ngoặc kép chưa đóng.');if(cell||row.length){row.push(cell.replace(/\r$/,''));rows.push(row)}const header=rows.shift()?.map(x=>x.trim().toLowerCase());if(!header||(!header.includes('text')&&!header.includes('title')))throw Error('CSV cần cột text hoặc title; id là tùy chọn.');return rows.map((r,i)=>Object.fromEntries(header.map((h,j)=>[h,r[j]||''])))}
$('#corpus-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2_000_000)throw Error('Tệp quá 2 MB.');const text=await file.text();let a;if(file.name.endsWith('.csv'))a=parseCSV(text);else if(file.name.endsWith('.jsonl'))a=text.split(/\r?\n/).filter(s=>s.trim()).map((s,i)=>{try{return JSON.parse(s)}catch{throw Error('JSONL không hợp lệ tại dòng '+(i+1))}});else{const x=JSON.parse(text);a=Array.isArray(x)?x:x.documents}if(!Array.isArray(a))throw Error('JSON cần mảng tài liệu hoặc trường documents.');const docs=a.map((d,i)=>({id:String(d.id||i+1),title:String(d.title||''),text:String(d.text||'')}));if(new Set(docs.map(d=>d.id)).size!==docs.length)throw Error('ID tài liệu trùng.');loadCorpus(docs,file.name,'Tệp của bạn');toast('Đọc tệp cục bộ. Nội dung không được tải lên máy chủ.')}catch(err){toast(err.message)}finally{e.target.value=''}};
$('#batch-queries').oninput=()=>{$('#batch-count').textContent=$('#batch-queries').value.split(/\r?\n/).filter(x=>x.trim()).length+' truy vấn';batch=null;$('#export-dataset').disabled=true};
$('#run-batch').onclick=()=>{const queries=$('#batch-queries').value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);if(!queries.length||queries.length>30){toast('Nhập từ 1 đến 30 truy vấn.');return}if(!ready)return;batch=null;setBusy(true);$('#batch-progress').textContent='Bắt đầu 0 / '+queries.length+'…';$('#batch-summary').textContent='';worker.postMessage({type:'batch',queries,options:options()})};
function queueExport(kind,payload){if(!payload)return;const id=++exportId;exports.set(id,{kind,payload:structuredClone(payload),corpusOrigin:$('#corpus-kind').textContent==='Tổng hợp'?'authored-synthetic':'user-provided'});worker.postMessage({type:'bundle',kind,requestId:id})}
$('#export-proof').onclick=()=>queueExport('proof',result);$('#export-dataset').onclick=()=>queueExport('dataset',batch);
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
async function sha(s){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}
for(const [name,lp,discrete] of [['SciFact',57.79,61.81],['NFCorpus',18.39,20.18],['FiQA',12.96,16.61]]){const row=el('div','chart-row'),bars=el('div','chart-pair');for(const value of [lp,discrete]){const bar=el('i');bar.style.width=value+'%';bar.title=value+'%';bars.append(bar)}row.append(el('span','',name),bars,el('b','',discrete.toFixed(2)+'%'));$('#research-chart').append(row)}
try{const responses=await Promise.all(['data/demo-corpus.json','data/typos.json','data/data-license.json'].map(p=>fetch(p).then(r=>{if(!r.ok)throw Error('Không tải được '+p);return r.json()})));demoDocuments=responses[0].documents;dictionary=responses[1];license=responses[2];makeWorker();loadCorpus(demoDocuments,'Knowledge Base · EN / VI','Tổng hợp')}catch(e){toast(e.message+' · Hãy tải lại trang.')}
tokenCount();

// Reusable pool UI. User content enters textContent only.
const poolPanel=el('section','panel pool-panel');poolPanel.id='pool-panel';poolPanel.innerHTML=`<div class="panel-heading"><h2><span class="section-num">04</span>Bộ đệm cho truy vấn sửa lỗi</h2><span class="badge soft">TOP-10 + TIES</span></div><p class="muted">Tập tài liệu bao phủ toàn bộ top-10 có thể xuất hiện trong bộ lỗi đã chọn. Dùng lại scorer và trọng số hiện tại để truy hồi trong tập này.</p><div class="pool-facts"><div><b id="pool-independent">—</b><span>Cận độc lập</span></div><div><b id="pool-coupled">—</b><span>Cùng truy vấn sửa</span></div><div><b id="pool-size">—</b><span>Bộ đệm chứng nhận</span></div></div><p id="pool-summary" aria-live="polite">Chạy kiểm chứng để tạo bộ đệm.</p><label for="pool-query" class="field-label">Thử một biến thể trong bộ lỗi đã chứng nhận</label><div class="pool-query-row"><input id="pool-query" placeholder="Chạy chứng nhận trước" disabled><button id="run-pool-query" class="button outline" disabled>Truy hồi từ bộ đệm</button></div><p id="pool-replay-result" class="muted" aria-live="polite"></p><details><summary>ID tài liệu trong bộ đệm & phạm vi</summary><p id="pool-ids" class="muted"></p><p class="muted">Giữ nguyên corpus, scorer, truy vấn gốc, bộ lỗi và ngân sách. Kết quả gồm mọi tài liệu bằng điểm ở ngưỡng thứ 10. Đây là bảo đảm tập kết quả của scorer, không phải bảo đảm mức liên quan hoặc câu trả lời RAG. Thuật toán chia miền và dominance có tiền lệ; novelty toàn cầu chưa được xác lập.</p></details>`;document.querySelector('[data-view="studio"]').append(poolPanel);
function clearPool(){const p=document.querySelector('#pool-size');if(!p)return;for(const id of ['pool-independent','pool-coupled','pool-size'])$('#'+id).textContent='—';$('#pool-summary').textContent='Chạy lại chứng nhận để tạo bộ đệm hợp lệ.';$('#pool-ids').textContent='';$('#pool-query').value='';$('#pool-query').disabled=true;$('#run-pool-query').disabled=true;$('#pool-replay-result').textContent=''}
function showPool(r){const p=r.possibleTopKPool;if(!p){clearPool();return}$('#pool-independent').textContent=fmt(p.independent.length);$('#pool-coupled').textContent=fmt(p.coupled.length);$('#pool-size').textContent=fmt(p.pool.length);$('#pool-summary').textContent=fmt(p.pool.length)+' / '+fmt(r.corpusSize)+' tài liệu · '+p.elapsedMs.toFixed(1)+' ms cho cận pool · '+(p.status==='safe_root_fallback'?'Đạt giới hạn tính toán; dùng cận gốc an toàn.':'Đã phủ mọi nhánh của phép chia đã chọn.')+' Gói chứng nhận tải ở trên có kèm pool và trace.';$('#pool-ids').textContent=p.documentIds.join(', ');$('#pool-query').value=r.witness.text;$('#pool-query').disabled=false;$('#run-pool-query').disabled=false;$('#pool-replay-result').textContent='Bộ đệm chưa được dùng để truy hồi.'}
$('#run-pool-query').onclick=()=>{if(!result||busy)return;$('#run-pool-query').disabled=true;$('#pool-replay-result').textContent='Đang kiểm tra biến thể và truy hồi…';worker.postMessage({type:'pool-replay',query:$('#pool-query').value,baseQuery:result.query,modelHash:result.modelHash,corpusHash:result.corpusHash})};

async function loadPoolEvidence(){try{const response=await fetch('data/pool-study.json');if(!response.ok)throw Error('evidence unavailable');const evidence=await response.json(),panel=el('section','panel pool-evidence');panel.innerHTML=`<div class="panel-heading"><h2>Bộ đệm top-k · thử nghiệm ứng dụng mới</h2><span class="badge soft">128 TRUY VẤN · 2 CORPUS</span></div><p class="muted">512 cấu hình được kiểm tra đầy đủ; không tạo nhãn thủ công. Bảng dưới: ngân sách sửa 2 token, top-10, giữ cả tài liệu bằng điểm ở ngưỡng.</p><div class="pool-table-wrap"><table class="research-table"><thead><tr><th>Corpus</th><th>Cận từng cặp</th><th>Pool chia miền</th><th>Hợp chính xác</th></tr></thead><tbody id="pool-evidence-body"></tbody></table></div><p id="pool-evidence-counts" class="muted"></p><p class="research-note">Chi phí ban đầu vẫn đáng kể: hòa vốn dự phóng trung vị 45 lần sửa trên ArguAna và 35 trên SciDocs. Không case nào ở cấu hình này hòa vốn trong 20 lần sửa đã đo. Dữ liệu dùng lỗi compact tổng hợp và 16 token đầu; toàn bộ 64 ArguAna và 3 SciDocs bị cắt. Thuật toán có tiền lệ UTK/dominance/partition, chưa xác lập novelty đủ Q1.</p><p class="muted">Thí nghiệm lớn chạy Python trên toàn corpus. Bản web tương tác tối đa 500 tài liệu, scorer và kênh lỗi riêng. Số liệu offline không đại diện tốc độ web.</p><div class="row-actions"><a class="button outline" href="https://github.com/TruongTQ261531/N-Gram/blob/main/pool_study/REPORT_VI.md" target="_blank" rel="noopener">Báo cáo & kết quả âm</a><a class="button outline" href="https://github.com/TruongTQ261531/N-Gram/tree/main/pool_study/results" target="_blank" rel="noopener">Factor, oracle & verifier</a><a class="text-button" href="data/pool-study.json" download>Tải số liệu JSON</a></div>`;document.querySelector('[data-view="research"] .research-facts').before(panel);for(const ds of ['arguana','scidocs']){const row=evidence.summary.find(x=>x.dataset===ds&&x.budget===2&&x.k===10),tr=el('tr');for(const value of [ds==='arguana'?'ArguAna':'SciDocs',row.mean_coupled.toFixed(2),row.mean_partitioned.toFixed(2),row.mean_exactUnion.toFixed(2)])tr.append(el('td','',value));panel.querySelector('tbody').append(tr)}const states=Object.values(evidence.verification).reduce((s,x)=>s+x.states,0),scores=Object.values(evidence.sourceReplay).reduce((s,x)=>s+x.independentTokenDocumentScores,0);panel.querySelector('#pool-evidence-counts').textContent=fmt(states)+' trạng thái–ngân sách được đối chiếu độc lập; '+fmt(scores)+' điểm token–tài liệu được dựng lại từ index nguồn. Không thiếu tài liệu oracle trong 512 cấu hình.'}catch(e){console.warn('Pool evidence could not be loaded',e.message)}}
loadPoolEvidence();
